test('REFERENCE-UI actual Notebook-oriented native workspace1586/tablet390: brand, real primary preview, deliberate assistant switch and no model/audio effect',async()=>{
 const f=await nativeViewBrowserFixture546({subjectId:'synthetic:erv-reviewer',agentRuns:true,humanDecisions:true,invoiceNavigation:true});try{
  const before=f.business();await f.page.setViewportSize({width:1586,height:992});await f.page.goto(f.tls.origin+'/t/tenant-a/workspace');await f.page.getByRole('button',{name:'Eingangsrechnungsprüfung — nur lesen',exact:true}).click();await f.page.locator('[id="shell.erv-human"][data-state="CURRENT_HUMAN_READ"]').waitFor();await f.page.locator('[id="shell.agent-panel"][data-state="CURRENT_SCOPE"]').waitFor();
  assert.equal(await f.page.locator('.product-brand strong').innerText(),'PanSphaira');assert.equal(await f.page.locator('.nav-label').filter({hasText:'Rechnungen'}).count(),1);assert.equal(await f.page.locator('.erv-financial-summary').isVisible(),true);assert.match(await f.page.locator('.erv-workspace-subtitle').innerText(),/AP-PAN516-MATCHED-01/,'Actual current invoice reference is visible without diagnostics');assert.equal(await f.page.locator('.erv-record-card').isVisible(),true);assert.equal(await f.page.locator('.erv-task-hero').count(),0,'No generic hero replacing concrete invoice context');assert.equal(await f.page.locator('.erv-quantity-summary .erv-quantity-unit').count(),3);assert.equal(await f.page.locator('.workspace-editor-disclosure').getAttribute('open'),null);assert.equal(await f.page.locator('.agent-technical-details').getAttribute('open'),null);
  const areas=await f.page.evaluate(()=>{const rect=s=>{const r=document.querySelector(s).getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height};};return {main:rect('[id="shell.main"]'),assistant:rect('[id="shell.agent-panel"]'),nav:rect('[id="shell.navigation"]'),overflow:document.documentElement.scrollWidth>innerWidth};});assert.equal(areas.overflow,false);assert.ok(areas.main.width>areas.assistant.width);assert.ok(areas.assistant.x>areas.main.x);assert.ok(areas.main.y<200&&areas.assistant.y<200);
  await f.page.locator('.erv-primary-action').focus();await f.page.keyboard.press('Enter');await f.page.locator('[id="shell.erv-human"][data-state="HUMAN_PREVIEW_ONLY"]').waitFor();assert.equal(f.business(),before);const primaryPhases=await f.page.evaluate(()=>{const p=document.querySelector('.erv-primary-action'),c=document.querySelector('.erv-confirm-action');return{preview:getComputedStyle(p).backgroundColor,confirm:getComputedStyle(c).backgroundColor,confirmText:c.textContent};});assert.notEqual(primaryPhases.preview,primaryPhases.confirm,'Confirmation alone is visually primary after preparation');assert.equal(primaryPhases.confirmText,'Lokale Evidenz bestätigen');assert.equal(f.requests.filter(r=>r.path.endsWith('/erv-human/decide')).length,0,'Primary preview must not confirm or persist');await f.page.getByRole('button',{name:'Fachvorschau abbrechen',exact:true}).click();
  for(const viewport of[{width:1024,height:768},{width:390,height:844}]){await f.page.setViewportSize(viewport);await f.page.evaluate(()=>window.scrollTo(0,0));assert.equal(await f.page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);if(viewport.width===1024){const primary=f.page.locator('.erv-primary-action');await primary.scrollIntoViewIfNeeded();await primary.focus();const reached=await primary.boundingBox();assert.ok(reached.y>=0&&reached.y+reached.height<=viewport.height,'Actual tablet scroll and keyboard focus reaches full native action');await f.page.keyboard.press('Enter');await f.page.locator('[id="shell.erv-human"][data-state="HUMAN_PREVIEW_ONLY"]').waitFor();await f.page.getByRole('button',{name:'Fachvorschau abbrechen',exact:true}).click();assert.equal(f.business(),before);}}
  await f.page.getByRole('button',{name:'Assistent',exact:true}).click();assert.equal(await f.page.locator('[id="shell.agent-panel"]').isVisible(),true);assert.equal(await f.page.locator('[id="shell.main"]').isVisible(),false);await f.page.getByRole('button',{name:'Ansicht bearbeiten',exact:true}).click();assert.equal(await f.page.locator('[id="shell.main"]').isVisible(),true,'Real assistant action returns from mobile assistant to the actual task/editor');assert.equal(await f.page.locator('[id="workspace.module-editor-details"]').getAttribute('open'),'');await f.page.locator('[id="workspace.module-editor-details"] > summary').click();await f.page.getByRole('button',{name:'Rechnung',exact:true}).click();assert.equal(await f.page.locator('[id="shell.main"]').isVisible(),true);assert.equal(await f.page.locator('[id="shell.agent-panel"]').isVisible(),false);assert.equal(f.business(),before);assert.equal(f.requests.filter(r=>r.path.endsWith('/agent-run/start')||r.path.endsWith('/agent-run/plan')||r.path.endsWith('/model-connection/probe')).length,0);assert.deepEqual(f.errors,[]);
 }finally{await f.close();}
});

